insert overwrite table ${schema}.dwm_sr_data_warehouse_tc_pb_reward_model_mini
select  shop_id
        ,item_id
        ,model_id
        ,status
        ,full_start_timestamp
        ,sum(imp_cnt) as imp_cnt
        ,sum(sold_cnt) as sold_cnt
        ,sum(gmv) as gmv

        ,${grass_region} as grass_region
        ,${regional_date} as regional_date
        ,${regional_hour} as regional_hour
        ,${regional_minute} as regional_minute
        ,date(date_timezone_convert(${regional_date}, ${regional_hour}, 'SG', ${grass_region}, "yyyy-MM-dd")) as local_date
        ,cast(date_timezone_convert(${regional_date}, ${regional_hour}, 'SG', ${grass_region}, "HH") as int) as local_hour
from    (
    select  T1.shop_id
            ,T1.item_id
            ,model_info.model_id as model_id
            ,model_info.status as status
            ,model_info.full_start_timestamp as full_start_timestamp
            ,T1.imp_cnt as imp_cnt
            ,0 as sold_cnt
            ,0 as gmv
    from    (
        select  *
        from    rcmd_feature.dws_sr_data_warehouse_tc_pb_realtime_feature_5min
        where   regional_date = ${regional_date}
          and   regional_hour = ${regional_hour}
          and   grass_region = ${grass_region}
          and   operation = 'impression'
          and   regional_minute between   cast(${regional_minute} as int)
          and   (
                    cast(${regional_minute} as int) + 15
                )
    ) as T1
    inner join (
        select  shop_id
                ,item_id
                ,exploded_model.*
        from    (
            select  a.shop_id
                    ,a.item_id
                    ,COLLECT_SET(named_struct('model_id', a.model_id, 'status', a.traffic_status, 'full_start_timestamp', a.full_start_timestamp)) AS model_list
            from    (
                select  *
                from    srdi_mart.dwd_sr_data_warehouse_tc_pb_winner_model_minf
                where   regional_date = ${regional_date}
                  and   regional_hour = ${regional_hour}
                  and   grass_region = ${grass_region}
                  and   regional_minute = (
                        select max(regional_minute) as regional_minute from srdi_mart.dwd_sr_data_warehouse_tc_pb_winner_model_minf
                        where grass_region in (${grass_region}) and regional_date = ${regional_date} and regional_hour = ${regional_hour}
                  )
                  and   traffic_status  in (1, 2)
            ) as a
            group by 1, 2
        ) a
        lateral view explode(model_list) exploded_model AS model_info
    ) as T2
    on      T1.shop_id = T2.shop_id
      and   T1.item_id = T2.item_id
    inner  join  (
        select  item_id
        ,shop_id
        from    srdi_mart.dwd_sr_data_warehouse_tc_pb_one_variation_minf
        where   regional_date = ${regional_date}
        and   regional_hour = ${regional_hour}
        and   grass_region = ${grass_region}
        and   regional_minute = (
            select max(regional_minute) as regional_minute from srdi_mart.dwd_sr_data_warehouse_tc_pb_one_variation_minf
            where grass_region in (${grass_region}) and regional_date = ${regional_date} and regional_hour = ${regional_hour}
        )
        and is_winner = 1
        group by 1,2
    )  as T3
    on T2.shop_id = T3.shop_id
    and T2.item_id = T3.item_id

    union all
    select  T1.shop_id
            ,T1.item_id
            ,T1.model_id
            ,T2.model_status
            ,T2.full_start_timestamp
            ,0 as imp_cnt
            ,T1.paid_sold_cnt as sold_cnt
            ,coalesce(T1.paid_sold_cnt, 0) * COALESCE(T2.bid_price, 0) as gmv
    from    (
        select  *
        from    rcmd_feature.dws_sr_data_warehouse_tc_pb_realtime_feature_5min
        where   regional_date = ${regional_date}
          and   regional_hour = ${regional_hour}
          and   grass_region = ${grass_region}
          and   operation = 'paid_order'
          and   regional_minute between   cast(${regional_minute} as int)
          and   (
                    cast(${regional_minute} as int) + 15
                )
    ) as T1
    inner join (
        select  a.shop_id
                ,a.item_id
                ,a.model_id
                ,max(a.bid_price) as bid_price
                ,max(traffic_status) as model_status
                ,max(full_start_timestamp) as full_start_timestamp
        from    (
            select  *
            from    srdi_mart.dwd_sr_data_warehouse_tc_pb_winner_model_minf
            where   regional_date = ${regional_date}
              and   regional_hour = ${regional_hour}
              and   grass_region = ${grass_region}
              and   regional_minute = (
                     select max(regional_minute) as regional_minute from srdi_mart.dwd_sr_data_warehouse_tc_pb_winner_model_minf
                     where grass_region in (${grass_region}) and regional_date = ${regional_date} and regional_hour = ${regional_hour}
              )
              and   traffic_status  in (1, 2)
        ) as a
        group by a.shop_id, a.item_id, a.model_id
    ) as T2
    on      T1.shop_id = T2.shop_id
      and   T1.item_id = T2.item_id
      and   T1.model_id = T2.model_id
       inner  join  (
        select  item_id
                ,shop_id
                ,model_id
        from    srdi_mart.dwd_sr_data_warehouse_tc_pb_one_variation_minf
        where   regional_date = ${regional_date}
        and   regional_hour = ${regional_hour}
        and   grass_region = ${grass_region}
        and   regional_minute = (
            select max(regional_minute) as regional_minute from srdi_mart.dwd_sr_data_warehouse_tc_pb_one_variation_minf
            where grass_region in (${grass_region}) and regional_date = ${regional_date} and regional_hour = ${regional_hour}
        )
        and is_winner = 1
        group by 1,2,3
    )  as T3
    on T2.shop_id = T3.shop_id
    and T2.item_id = T3.item_id
    and T2.model_id= T3.model_id
)
group by 1, 2, 3, 4, 5
